  'privacy.title': 'Política de Privacidade',
  'privacy.intro': 'Esta página explica, em linguagem simples, que dados o Jynlo utiliza durante o piloto, para que servem e quais são os teus direitos.',
  'privacy.controller.title': 'Responsável pelo tratamento',
  'privacy.controller.text': 'O projeto Jynlo gere os dados tratados na plataforma. A identificação jurídica completa do responsável (nome ou entidade, NIF e morada) está pendente de confirmação antes da abertura pública/comercial.',
  'privacy.purposes.title': 'Dados e finalidades',
  'privacy.purposes.text': 'Usamos os dados de conta e perfil para autenticação, gestão da conta, descoberta de pessoas e atividades, participação em sessões, comunicação, segurança, suporte e funcionamento do piloto. Dados opcionais devem ser usados apenas quando necessários às funcionalidades escolhidas.',
  'privacy.location.title': 'Localização',
  'privacy.location.text': 'Quando autorizas a localização do dispositivo, ela é usada para ordenar ou procurar atividades próximas. A localização do dispositivo não deve ser guardada como histórico. A localização associada a uma sessão ou recinto pode ficar guardada como parte desse conteúdo.',
  'privacy.retention.title': 'Conservação',
  'privacy.retention.text': 'Os prazos de conservação de mensagens, presenças, contactos e contas inativas ainda serão formalizados antes da abertura pública. Durante o piloto, os dados devem ser mantidos apenas pelo período necessário ao funcionamento, segurança e validação do serviço.',
  'privacy.processors.title': 'Prestadores e subcontratantes',
  'privacy.processors.text': 'O serviço pode recorrer a fornecedores de infraestrutura, email e autenticação necessários ao funcionamento da plataforma. A lista e as condições aplicáveis serão consolidadas na versão final desta política.',
  'privacy.rights.title': 'Os teus direitos',
  'privacy.rights.text': 'Podes pedir acesso, correção, portabilidade ou apagamento dos teus dados e colocar questões sobre o tratamento através do contacto indicado nesta página. O produto está a implementar mecanismos de exportação e eliminação de conta.',
  'privacy.security.title': 'Segurança',
  'privacy.security.text': 'O Jynlo usa autenticação, controlos de acesso e mecanismos de segurança destinados a proteger as contas e os dados. Nenhum sistema elimina totalmente o risco, pelo que incidentes relevantes devem ser tratados e comunicados quando aplicável.',

  'terms.title': 'Termos de Utilização',
  'terms.intro': 'Estes termos provisórios definem as regras básicas de utilização do Jynlo durante o piloto.',
  'terms.scope.title': 'Âmbito do piloto',
  'terms.scope.text': 'O Jynlo ajuda pessoas a encontrar locais, atividades e outros praticantes. Durante o piloto, algumas funcionalidades podem mudar, ficar indisponíveis ou ser ajustadas com base no feedback e nos testes.',
  'terms.eligibility.title': 'Idade e conta',
  'terms.eligibility.text': 'A utilização da plataforma exige idade mínima de 18 anos. Deves fornecer dados de conta válidos, proteger as tuas credenciais e não usar contas de terceiros.',
  'terms.conduct.title': 'Conduta',
  'terms.conduct.text': 'Não é permitido assediar, ameaçar, discriminar, enganar outros utilizadores, publicar conteúdo ilegal ou abusivo, fazer spam, tentar obter acesso não autorizado ou usar a plataforma para fins incompatíveis com a comunidade desportiva.',
  'terms.sessions.title': 'Sessões e fiabilidade',
  'terms.sessions.text': 'Ao criar ou participar numa sessão, deves fornecer informação correta e agir de boa-fé. Presenças, faltas e cancelamentos podem contribuir para indicadores de fiabilidade. As regras e limiares aplicáveis devem ser apresentados ao utilizador antes de produzirem consequências.',
  'terms.moderation.title': 'Moderação e segurança',
  'terms.moderation.text': 'Conteúdo ou comportamentos que violem estas regras podem ser analisados, ocultados ou removidos e contas podem ser limitadas quando necessário para proteger utilizadores e a plataforma. Sempre que aplicável, deve existir possibilidade de contestação ou revisão.',
  'terms.account.title': 'Conta e dados',
  'terms.account.text': 'Podes atualizar os teus dados de perfil e exercer os direitos descritos na Política de Privacidade. Estão a ser implementadas opções de exportação de dados e eliminação da conta.',
  'terms.changes.title': 'Alterações e contacto',
  'terms.changes.text': 'Estes termos podem ser atualizados durante o piloto. Alterações materiais devem ser comunicadas de forma clara. Para questões, utiliza o contacto indicado nesta página.',

